import java.util.*;

public class Main {
    int hammingDistance(int x, int y) {
        int count = 0;
        for (int i = 0; i < 32; i++) {                              // always checks all 32 positions
            int bitX = (x >> i) & 1;
            int bitY = (y >> i) & 1;
            if (bitX != bitY) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.hammingDistance(1, 4));
    }
}

